public struct ActivityBucket {
    public var ts: String
    public var counts: [ChannelCount]

    /// Default memberwise initializers are never public by default, so we
    /// declare one manually.
    public init(ts: String, counts: [ChannelCount]) {
        self.ts = ts
        self.counts = counts
    }
}

extension ActivityBucket: Equatable, Hashable {
    public static func == (lhs: ActivityBucket, rhs: ActivityBucket) -> Bool {
        if lhs.ts != rhs.ts {
            return false
        }
        if lhs.counts != rhs.counts {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(ts)
        hasher.combine(counts)
    }
}

