/**
 * Состояние локальной базы: сколько занимает, что в ней лежит, доступен ли
 * полнотекстовый индекс. Для экрана «Хранилище» и диагностики.
 *
 * Пустая строка в `first_start_at`/`last_end_at` означает «истории нет»
 * (Option в FFI-контрактах ядра сознательно не используется).
 */
public struct StoreInfo {
    /**
     * Полный путь к файлу базы.
     */
    public var path: String
    /**
     * Версия схемы (`PRAGMA user_version`).
     */
    public var schemaVersion: Int64
    /**
     * Размер основной базы в байтах.
     */
    public var sizeBytes: UInt64
    /**
     * Размер WAL-файла рядом с базой в байтах (0, если его нет).
     */
    public var walBytes: UInt64
    public var intervals: Int64
    public var intervalTexts: Int64
    public var voiceEvents: Int64
    /**
     * Доступен ли FTS5 (иначе поиск идёт по LIKE).
     */
    public var fts5: Bool
    public var firstStartAt: String
    public var lastEndAt: String

    /// Default memberwise initializers are never public by default, so we
    /// declare one manually.
    public init(
        /* 
         * Полный путь к файлу базы.
         */ path: String,
        /* 
            * Версия схемы (`PRAGMA user_version`).
            */ schemaVersion: Int64,
        /* 
            * Размер основной базы в байтах.
            */ sizeBytes: UInt64,
        /* 
            * Размер WAL-файла рядом с базой в байтах (0, если его нет).
            */ walBytes: UInt64, intervals: Int64, intervalTexts: Int64, voiceEvents: Int64,
        /* 
            * Доступен ли FTS5 (иначе поиск идёт по LIKE).
            */ fts5: Bool, firstStartAt: String, lastEndAt: String
    ) {
        self.path = path
        self.schemaVersion = schemaVersion
        self.sizeBytes = sizeBytes
        self.walBytes = walBytes
        self.intervals = intervals
        self.intervalTexts = intervalTexts
        self.voiceEvents = voiceEvents
        self.fts5 = fts5
        self.firstStartAt = firstStartAt
        self.lastEndAt = lastEndAt
    }
}

extension StoreInfo: Equatable, Hashable {
    public static func == (lhs: StoreInfo, rhs: StoreInfo) -> Bool {
        if lhs.path != rhs.path {
            return false
        }
        if lhs.schemaVersion != rhs.schemaVersion {
            return false
        }
        if lhs.sizeBytes != rhs.sizeBytes {
            return false
        }
        if lhs.walBytes != rhs.walBytes {
            return false
        }
        if lhs.intervals != rhs.intervals {
