/**
 * VAD configuration. Silence detection drives interval cutting.
 */
public struct VadConfig {
    /**
     * Silero speech-probability threshold (0.0..1.0). Frames below count as
     * silence (subject to the RMS safety net below).
     */
    public var sileroThreshold: Float
    /**
     * RMS safety net: a frame the VAD calls "silence" is still treated as
     * speech if its normalized RMS >= this value. Ported default: 0.008.
     */
    public var rmsFallback: Float

    /// Default memberwise initializers are never public by default, so we
    /// declare one manually.
    public init(
        /* 
         * Silero speech-probability threshold (0.0..1.0). Frames below count as
         * silence (subject to the RMS safety net below).
         */ sileroThreshold: Float,
        /* 
            * RMS safety net: a frame the VAD calls "silence" is still treated as
            * speech if its normalized RMS >= this value. Ported default: 0.008.
            */ rmsFallback: Float
    ) {
        self.sileroThreshold = sileroThreshold
        self.rmsFallback = rmsFallback
    }
}

extension VadConfig: Equatable, Hashable {
    public static func == (lhs: VadConfig, rhs: VadConfig) -> Bool {
        if lhs.sileroThreshold != rhs.sileroThreshold {
            return false
        }
        if lhs.rmsFallback != rhs.rmsFallback {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(sileroThreshold)
        hasher.combine(rmsFallback)
    }
}

