/**
 * Implemented by the platform (UniFFI callback interface on Swift/Kotlin).
 */
public protocol CoreEventListener: AnyObject {
    func onEvent(event: CoreEvent)
}

/// Magic number for the Rust proxy to call using the same mechanism as every other method,
/// to free the callback once it's dropped by Rust.
private let IDX_CALLBACK_FREE: Int32 = 0
// Callback return codes
private let UNIFFI_CALLBACK_SUCCESS: Int32 = 0
private let UNIFFI_CALLBACK_ERROR: Int32 = 1
private let UNIFFI_CALLBACK_UNEXPECTED_ERROR: Int32 = 2

/// Put the implementation in a struct so we don't pollute the top-level namespace
private enum UniffiCallbackInterfaceCoreEventListener {
    /// Create the VTable using a series of closures.
    /// Swift automatically converts these into C callback functions.
    static var vtable: UniffiVTableCallbackInterfaceCoreEventListener = .init(
        onEvent: { (
            uniffiHandle: UInt64,
            event: RustBuffer,
            _: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceCoreEventListener.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.onEvent(
                    event: FfiConverterTypeCoreEvent.lift(event)
                )
            }

            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        uniffiFree: { (uniffiHandle: UInt64) in
            let result = try? FfiConverterCallbackInterfaceCoreEventListener.handleMap.remove(handle: uniffiHandle)
            if result == nil {
                print("Uniffi callback interface CoreEventListener: handle missing in uniffiFree")
            }
        }
    )
}

private func uniffiCallbackInitCoreEventListener() {
    uniffi_transcriber_core_fn_init_callback_vtable_coreeventlistener(&UniffiCallbackInterfaceCoreEventListener.vtable)
}

